using Contoso.Orders;

namespace Contoso.Orders.Tests;

[TestClass]
public sealed class OrderServiceTests
{
    private readonly OrderService _sut;

    public OrderServiceTests()
    {
        _sut = new OrderService();
    }

    private static List<OrderItem> CreateItems(int count = 1) =>
        Enumerable.Range(1, count).Select(i => new OrderItem
        {
            ProductName = $"Product {i}",
            Price = 10.00m * i,
            Quantity = i
        }).ToList();

    #region CreateOrder - Happy Path

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithCorrectCustomerId()
    {
        // Arrange
        var items = CreateItems();

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.AreEqual("customer-1", order.CustomerId);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithNonEmptyId()
    {
        // Arrange
        var items = CreateItems();

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.IsNotNull(order.Id);
        Assert.AreNotEqual(string.Empty, order.Id);
    }

    [TestMethod]
    public void CreateOrder_WithValidItems_ReturnsOrderWithAssignedItems()
    {
        // Arrange
        var items = CreateItems(2);

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.HasCount(2, order.Items);
    }

    [TestMethod]
    public void CreateOrder_WithSingleItem_CalculatesTotalCorrectly()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "Widget", Price = 25.00m, Quantity = 3 }
        };

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.AreEqual(75.00m, order.Total);
    }

    [TestMethod]
    public void CreateOrder_WithMultipleItems_SumsTotalCorrectly()
    {
        // Arrange
        var items = new List<OrderItem>
        {
            new() { ProductName = "A", Price = 10.00m, Quantity = 2 },
            new() { ProductName = "B", Price = 5.00m, Quantity = 4 }
        };

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        Assert.AreEqual(40.00m, order.Total); // (10*2) + (5*4)
    }

    [TestMethod]
    public void CreateOrder_SetsCreatedAtToRecentTime()
    {
        // Arrange
        var before = DateTime.UtcNow;
        var items = CreateItems();

        // Act
        var order = _sut.CreateOrder("customer-1", items);

        // Assert
        var after = DateTime.UtcNow;
        Assert.IsTrue(order.CreatedAt >= before && order.CreatedAt <= after);
    }

    #endregion

    #region CreateOrder - Validation

    [TestMethod]
    public void CreateOrder_WithNullCustomerId_ThrowsArgumentNullException()
    {
        // Arrange
        var items = CreateItems();

        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder(null!, items));
        Assert.AreEqual("customerId", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithNullItems_ThrowsArgumentNullException()
    {
        // Act & Assert
        var ex = Assert.ThrowsExactly<ArgumentNullException>(
            () => _sut.CreateOrder("customer-1", null!));
        Assert.AreEqual("items", ex.ParamName);
    }

    [TestMethod]
    public void CreateOrder_WithEmptyItems_ThrowsInvalidOperationException()
    {
        // Arrange
        var emptyItems = new List<OrderItem>();

        // Act & Assert
        var ex = Assert.ThrowsExactly<InvalidOperationException>(
            () => _sut.CreateOrder("customer-1", emptyItems));
        Assert.Contains("no items", ex.Message, StringComparison.OrdinalIgnoreCase);
    }

    #endregion

    #region GetOrder

    [TestMethod]
    public void GetOrder_WithExistingId_ReturnsMatchingOrder()
    {
        // Arrange
        var created = _sut.CreateOrder("customer-1", CreateItems());

        // Act
        var retrieved = _sut.GetOrder(created.Id);

        // Assert
        Assert.IsNotNull(retrieved);
        Assert.AreEqual(created.Id, retrieved.Id);
    }

    [TestMethod]
    public void GetOrder_WithNonExistentId_ReturnsNull()
    {
        // Act
        var result = _sut.GetOrder("non-existent-id");

        // Assert
        Assert.IsNull(result);
    }

    #endregion

    #region GetOrdersByCustomer

    [TestMethod]
    public void GetOrdersByCustomer_WithMultipleOrders_ReturnsAllForCustomer()
    {
        // Arrange
        _sut.CreateOrder("customer-1", CreateItems());
        _sut.CreateOrder("customer-1", CreateItems());
        _sut.CreateOrder("customer-2", CreateItems());

        // Act
        var orders = _sut.GetOrdersByCustomer("customer-1");

        // Assert
        Assert.HasCount(2, orders);
    }

    [TestMethod]
    public void GetOrdersByCustomer_WithNoOrders_ReturnsEmptyList()
    {
        // Act
        var orders = _sut.GetOrdersByCustomer("unknown-customer");

        // Assert
        Assert.IsEmpty(orders);
    }

    #endregion
}

using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _sut;

    public PriceCalculatorTests()
    {
        _sut = new PriceCalculator();
    }

    #region CalculateTotal - Happy Path

    [TestMethod]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "No tax")]
    [DataRow(10.00, 2, 0.1, 22.00, DisplayName = "10% tax")]
    [DataRow(25.00, 4, 0.2, 120.00, DisplayName = "20% tax")]
    [DataRow(0.00, 5, 0.1, 0.00, DisplayName = "Zero price")]
    [DataRow(10.00, 0, 0.1, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        // Act
        var result = _sut.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        // Assert
        Assert.AreEqual((decimal)expected, result);
    }

    #endregion

    #region CalculateTotal - Validation

    [TestMethod]
    public void CalculateTotal_WithNegativeQuantity_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, -1, 0.1m));
        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void CalculateTotal_WithNegativeUnitPrice_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(-5m, 2, 0.1m));
        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Negative tax rate")]
    [DataRow(1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_WithInvalidTaxRate_ThrowsArgumentOutOfRangeException(double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, 2, (decimal)taxRate));
        Assert.AreEqual("taxRate", ex.ParamName);
    }

    #endregion

    #region ApplyDiscount

    [TestMethod]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off")]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "No discount")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% off")]
    [DataRow(200.00, 50.0, 100.00, DisplayName = "50% off")]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        double price, double discount, double expected)
    {
        var result = _sut.ApplyDiscount((decimal)price, (decimal)discount);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Negative discount")]
    [DataRow(101.0, DisplayName = "Discount above 100")]
    public void ApplyDiscount_WithInvalidPercent_ThrowsArgumentOutOfRangeException(double discount)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.ApplyDiscount(100m, (decimal)discount));
    }

    #endregion

    #region FormatPrice

    [TestMethod]
    public void FormatPrice_WithDefaultCurrency_FormatsWithDollarSign()
    {
        var result = _sut.FormatPrice(42.50m);
        Assert.AreEqual("$42.50", result);
    }

    [TestMethod]
    public void FormatPrice_WithCustomCurrency_UsesProvidedSymbol()
    {
        var result = _sut.FormatPrice(42.50m, "€");
        Assert.AreEqual("€42.50", result);
    }

    [TestMethod]
    public void FormatPrice_RoundsToTwoDecimalPlaces()
    {
        var result = _sut.FormatPrice(9.999m);
        Assert.AreEqual("$10.00", result);
    }

    #endregion
}

