using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _sut;

    public PriceCalculatorTests()
    {
        _sut = new PriceCalculator();
    }

    #region CalculateTotal - Happy Path

    [TestMethod]
    [DataRow(10.00, 2, 0.0, 20.00, DisplayName = "No tax")]
    [DataRow(10.00, 2, 0.1, 22.00, DisplayName = "10% tax")]
    [DataRow(25.00, 4, 0.2, 120.00, DisplayName = "20% tax")]
    [DataRow(0.00, 5, 0.1, 0.00, DisplayName = "Zero price")]
    [DataRow(10.00, 0, 0.1, 0.00, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithValidInputs_ReturnsExpected(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        // Act
        var result = _sut.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        // Assert
        Assert.AreEqual((decimal)expected, result);
    }

    #endregion

    #region CalculateTotal - Validation

    [TestMethod]
    public void CalculateTotal_WithNegativeQuantity_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, -1, 0.1m));
        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void CalculateTotal_WithNegativeUnitPrice_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(-5m, 2, 0.1m));
        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Negative tax rate")]
    [DataRow(1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_WithInvalidTaxRate_ThrowsArgumentOutOfRangeException(double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.CalculateTotal(10m, 2, (decimal)taxRate));
        Assert.AreEqual("taxRate", ex.ParamName);
    }

    #endregion

    #region ApplyDiscount

    [TestMethod]
    [DataRow(100.00, 10.0, 90.00, DisplayName = "10% off")]
    [DataRow(100.00, 0.0, 100.00, DisplayName = "No discount")]
    [DataRow(100.00, 100.0, 0.00, DisplayName = "100% off")]
    [DataRow(200.00, 50.0, 100.00, DisplayName = "50% off")]
    public void ApplyDiscount_WithValidInputs_ReturnsExpected(
        double price, double discount, double expected)
    {
        var result = _sut.ApplyDiscount((decimal)price, (decimal)discount);
        Assert.AreEqual((decimal)expected, result);
    }

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Negative discount")]
    [DataRow(101.0, DisplayName = "Discount above 100")]
    public void ApplyDiscount_WithInvalidPercent_ThrowsArgumentOutOfRangeException(double discount)
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _sut.ApplyDiscount(100m, (decimal)discount));
    }

    #endregion

    #region FormatPrice

    [TestMethod]
    public void FormatPrice_WithDefaultCurrency_FormatsWithDollarSign()
    {
        var result = _sut.FormatPrice(42.50m);
        Assert.AreEqual("$42.50", result);
    }

    [TestMethod]
    public void FormatPrice_WithCustomCurrency_UsesProvidedSymbol()
    {
        var result = _sut.FormatPrice(42.50m, "€");
        Assert.AreEqual("€42.50", result);
    }

    [TestMethod]
    public void FormatPrice_RoundsToTwoDecimalPlaces()
    {
        var result = _sut.FormatPrice(9.999m);
        Assert.AreEqual("$10.00", result);
    }

    #endregion
}

